import json
from src.nodes.base import BaseNode
from src.runtime.layout import (
    get_semantic_layout_engine,
    get_relationship_graph,
    reset_relationship_graph_for_tests,
    get_affordance_engine,
    AssetRelationship,
)

class Hou_Mcp_Layout_Graph(BaseNode):
    name = "hou_mcp_layout_graph"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("assets_json",  "string", widget_type="text", default="[]")
        self.add_input("environment",  "string", widget_type="text", default="western_room")
        self.add_output("relationships_json", "string")
        self.add_output("relationship_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw = (inputs.get("assets_json") or "").strip()
        environment = (inputs.get("environment") or "").strip()

        try:
            assets = json.loads(raw) if raw else []
        except Exception:
            self.log_error("assets_json is not valid JSON.")
            return {"relationships_json": "[]", "relationship_count": 0, "exec_out": True}

        try:
            from src.runtime.layout.anchor_layout_engine import get_anchor_layout_engine
            eng = get_affordance_engine()
            graph = get_relationship_graph()
            graph.clear()

            anchor_result = get_anchor_layout_engine().place_anchors(assets, environment)
            anchor_id_set = {p.anchor_id for p in anchor_result.placements}

            for asset in assets:
                asset_id = str(asset.get("asset_id") or asset.get("name") or "")
                a_type = eng.infer_type(asset)
                aff = eng.get_affordances(a_type)

                if asset_id in anchor_id_set:
                    for other in assets:
                        other_id = str(other.get("asset_id") or other.get("name") or "")
                        if other_id == asset_id:
                            continue
                        other_type = eng.infer_type(other)
                        if eng.can_support(a_type, other_type):
                            graph.add_relationship(AssetRelationship(
                                from_asset_id=other_id,
                                to_asset_id=asset_id,
                                relationship_type="supports",
                            ))
                        elif eng.can_surround(a_type, other_type):
                            graph.add_relationship(AssetRelationship(
                                from_asset_id=other_id,
                                to_asset_id=asset_id,
                                relationship_type="around",
                            ))
                else:
                    mode = aff.placement_mode
                    if mode in ("wall_only", "wall_or_ceiling"):
                        graph.add_relationship(AssetRelationship(
                            from_asset_id=asset_id,
                            to_asset_id="wall",
                            relationship_type="attached_to",
                        ))
                    elif mode == "against_wall":
                        graph.add_relationship(AssetRelationship(
                            from_asset_id=asset_id,
                            to_asset_id="wall",
                            relationship_type="against",
                        ))
                    elif mode == "corner":
                        graph.add_relationship(AssetRelationship(
                            from_asset_id=asset_id,
                            to_asset_id="corner",
                            relationship_type="near",
                        ))

            rels = [r.to_dict() for r in graph.all_relationships()]
            return {
                "relationships_json": json.dumps(rels, sort_keys=True, indent=2),
                "relationship_count": len(rels),
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Layout graph build failed: {exc}")
            return {"relationships_json": "[]", "relationship_count": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Layout_Graph
